\begin{definition}
\label{definition-support-module}
Let $R$ be a ring and let $M$ be an $R$-module.
The {\it support of $M$} is the set
$$
\text{Supp}(M)
=
\{
\mathfrak p \in \Spec(R)
\mid
M_{\mathfrak p} \not = 0
\}
$$
\end{definition}

choices.target_text:
\begin{definition}
\label{definition-support-module}
Soit $R$ un anneau et soit $M$ un $R$-module.
Le {\it support de $M$} est l'ensemble
$$
\text{Supp}(M)
=
\{
\mathfrak p \in \Spec(R)
\mid
M_{\mathfrak p} \not = 0
\}
$$
\end{definition}

choices.source_text:
\begin{lemma}
\label{lemma-support-zero}
\begin{slogan}
A module over a ring has empty support if and only if it is the trivial module.
\end{slogan}
Let $R$ be a ring. Let $M$ be an $R$-module. Then
$$
M = (0) \Leftrightarrow \text{Supp}(M) = \emptyset.
$$
\end{lemma}

\begin{proof}
Actually,
Lemma \ref{lemma-characterize-zero-local}
even shows that $\text{Supp}(M)$ always contains a maximal ideal
if $M$ is not zero.
\end{proof}

choices.target_text:
\begin{lemma}
\label{lemma-support-zero}
\begin{slogan}
Un module sur un anneau est de support vide si et seulement s'il est nul.
\end{slogan}
Soit $R$ un anneau. Soit $M$ un $R$-module. Alors
$$
M = (0) \Leftrightarrow \text{Supp}(M) = \emptyset.
$$
\end{lemma}

\begin{proof}
En fait, le
lemme \ref{lemma-characterize-zero-local}
montre même que $\text{Supp}(M)$ contient toujours un idéal maximal
si $M$ n'est pas nul.
\end{proof}

