\begin{definition}
\label{definition-annihilator}
Let $R$ be a ring. Let $M$ be an $R$-module.
\begin{enumerate}
\item Given an element $m \in M$ the {\it annihilator of $m$}
is the ideal
$$
\text{Ann}_R(m) = \text{Ann}(m) = \{f \in R \mid fm = 0\}.
$$
\item The {\it annihilator of $M$}
is the ideal
$$
\text{Ann}_R(M) = \text{Ann}(M) = \{f \in R \mid fm = 0\ \forall m \in M\}.
$$
\end{enumerate}
\end{definition}

choices.target_text:
\begin{definition}
\label{definition-annihilator}
Soit $R$ un anneau. Soit $M$ un $R$-module.
\begin{enumerate}
\item Étant donné un élément $m \in M$, l'{\it annulateur de $m$}
est l'idéal
$$
\text{Ann}_R(m) = \text{Ann}(m) = \{f \in R \mid fm = 0\}.
$$
\item L'{\it annulateur de $M$}
est l'idéal
$$
\text{Ann}_R(M) = \text{Ann}(M) = \{f \in R \mid fm = 0\ \forall m \in M\}.
$$
\end{enumerate}
\end{definition}

