\begin{lemma}
\label{lemma-support-element}
Let $R$ be a ring, let $M$ be an $R$-module, and let $m \in M$.
Then $\mathfrak p \in V(\text{Ann}(m))$ if and only if
$m$ does not map to zero in $M_\mathfrak p$.
\end{lemma}

\begin{proof}
We may replace $M$ by $Rm \subset M$. Then (1) $\text{Ann}(m) = \text{Ann}(M)$
and (2) $m$ does not map to zero in $M_\mathfrak p$ if and only if
$\mathfrak p \in \text{Supp}(M)$.
The result now follows from Lemma \ref{lemma-support-closed}.
\end{proof}

choices.target_text:
\begin{lemma}
\label{lemma-support-element}
Soit $R$ un anneau, soit $M$ un $R$-module et soit $m \in M$.
Alors $\mathfrak p \in V(\text{Ann}(m))$ si et seulement si
$m$ ne s'envoie pas sur zéro dans $M_\mathfrak p$.
\end{lemma}

\begin{proof}
Nous pouvons remplacer $M$ par $Rm \subset M$. Alors (1) $\text{Ann}(m) = \text{Ann}(M)$
et (2) $m$ ne s'envoie pas sur zéro dans $M_\mathfrak p$ si et seulement si
$\mathfrak p \in \text{Supp}(M)$.
Le résultat découle maintenant du lemme \ref{lemma-support-closed}.
\end{proof}

