\begin{lemma}
\label{lemma-support-quotient}
Let $R$ be a ring and let $M$ be an $R$-module.
\begin{enumerate}
\item If $M$ is finite then the support
of $M/IM$ is $\text{Supp}(M) \cap V(I)$.
\item If $N \subset M$, then $\text{Supp}(N) \subset
\text{Supp}(M)$.
\item If $Q$ is a quotient module of $M$ then $\text{Supp}(Q) \subset
\text{Supp}(M)$.
\item If $0 \to N \to M \to Q \to 0$ is a short exact sequence
then $\text{Supp}(M) = \text{Supp}(Q) \cup \text{Supp}(N)$.
\end{enumerate}
\end{lemma}

\begin{proof}
The functors $M \mapsto M_{\mathfrak p}$ are exact. This immediately
implies all but the first assertion. For the first assertion
we need to show that $M_\mathfrak p \not = 0$ and
$I \subset \mathfrak p$ implies $(M/IM)_{\mathfrak p}
= M_\mathfrak p/IM_\mathfrak p \not = 0$. This follows
from Nakayama's Lemma \ref{lemma-NAK}.
\end{proof}

choices.target_text:
\begin{lemma}
\label{lemma-support-quotient}
Soit $R$ un anneau et soit $M$ un $R$-module.
\begin{enumerate}
\item Si $M$ est de type fini, alors le support
de $M/IM$ est $\text{Supp}(M) \cap V(I)$.
\item Si $N \subset M$, alors $\text{Supp}(N) \subset
\text{Supp}(M)$.
\item Si $Q$ est un module quotient de $M$, alors $\text{Supp}(Q) \subset
\text{Supp}(M)$.
\item Si $0 \to N \to M \to Q \to 0$ est une suite exacte courte,
alors $\text{Supp}(M) = \text{Supp}(Q) \cup \text{Supp}(N)$.
\end{enumerate}
\end{lemma}

\begin{proof}
Les foncteurs $M \mapsto M_{\mathfrak p}$ sont exacts. Cela implique immédiatement
toutes les assertions sauf la première. Pour la première assertion,
nous devons montrer que $M_\mathfrak p \not = 0$ et
$I \subset \mathfrak p$ impliquent $(M/IM)_{\mathfrak p}
= M_\mathfrak p/IM_\mathfrak p \not = 0$. Cela résulte
du lemme de Nakayama \ref{lemma-NAK}.
\end{proof}

