\begin{lemma}
\label{lemma-going-up-down-composition}
Suppose $R \to S$ and $S \to T$ are ring maps satisfying
going down. Then so does $R \to T$. Similarly for going up.
\end{lemma}

\begin{proof}
According to Lemma \ref{lemma-going-up-down-specialization}
this follows from
Topology, Lemma \ref{topology-lemma-lift-specialization-composition}
\end{proof}

choices.target_text:
\begin{lemma}
\label{lemma-going-up-down-composition}
Supposons que $R \to S$ et $S \to T$ soient des morphismes d'anneaux vérifiant
la propriété de descente. Alors $R \to T$ la vérifie aussi. Il en va de même pour la propriété de montée.
\end{lemma}

\begin{proof}
D'après le lemme \ref{lemma-going-up-down-specialization},
cela résulte du
lemme de Topologie \ref{topology-lemma-lift-specialization-composition}.
\end{proof}

