\begin{lemma}
\label{lemma-constructible-stable-specialization-closed}
Let $R$ be a ring. Let $E \subset \Spec(R)$ be a constructible subset.
\begin{enumerate}
\item If $E$ is stable under specialization, then $E$ is closed.
\item If $E$ is stable under generalization, then $E$ is open.
\end{enumerate}
\end{lemma}

\begin{proof}
First proof. The first assertion
follows from Lemma \ref{lemma-image-stable-specialization-closed}
combined with Lemma \ref{lemma-constructible-is-image}.
The second follows because the complement of a constructible
set is constructible
(see Topology, Lemma \ref{topology-lemma-constructible}),
the first part of the lemma and Topology,
Lemma \ref{topology-lemma-open-closed-specialization}.

\medskip\noindent
Second proof. Since $\Spec(R)$ is a spectral space by
Lemma \ref{lemma-spec-spectral} this is a special case of
Topology, Lemma
\ref{topology-lemma-constructible-stable-specialization-closed}.
\end{proof}

choices.target_text:
\begin{lemma}
\label{lemma-constructible-stable-specialization-closed}
Soit $R$ un anneau. Soit $E \subset \Spec(R)$ une partie constructible.
\begin{enumerate}
\item Si $E$ est stable par spécialisation, alors $E$ est fermée.
\item Si $E$ est stable par généralisation, alors $E$ est ouverte.
\end{enumerate}
\end{lemma}

\begin{proof}
Première preuve. La première assertion
résulte du lemme \ref{lemma-image-stable-specialization-closed}
combiné au lemme \ref{lemma-constructible-is-image}.
La seconde résulte du fait que le complémentaire d'une partie constructible
est constructible
(voir Topologie, lemme \ref{topology-lemma-constructible}),
de la première partie du lemme et du
lemme de Topologie \ref{topology-lemma-open-closed-specialization}.

\medskip\noindent
Deuxième preuve. Puisque $\Spec(R)$ est un espace spectral d'après le
lemme \ref{lemma-spec-spectral}, il s'agit d'un cas particulier du
lemme de Topologie
\ref{topology-lemma-constructible-stable-specialization-closed}.
\end{proof}

